import { useNavigate } from "react-router-dom";

const NewEntry = () => {
  const navigate = useNavigate();
  return (
    <div className="p-6">
      <h1 className="text-2xl font-semibold mb-4">Create New Entry</h1>
      <textarea
        className="w-full h-40 border p-3 rounded-lg"
        placeholder="Write your diary entry..."
      ></textarea>
      <div className="mt-4 flex space-x-4">
        <button
          className="bg-green-500 text-white px-6 py-2 rounded-xl"
          onClick={() => navigate("/dashboard")}
        >
          Save
        </button>
        <button
          className="bg-gray-400 text-white px-6 py-2 rounded-xl"
          onClick={() => navigate("/dashboard")}
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default NewEntry;
